-- 0015_devices_zones — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- E4 zones and platform binding (D-29, 07-integrations "Device platform"): a project (site) is one mall on the
-- device platform; its zones are the mall's areas (stores) and gates; each device channel counts one gate.

-- site: the mall on the device platform, and the per-project switch for offline alerts (Vlad, 3 Nov: alerts are
-- turned on and off by a checkbox; off by default so a mall that is not live yet opens no actions).
ALTER TABLE site ADD COLUMN platform_ref text CHECK (platform_ref <> '');
CREATE UNIQUE INDEX site_platform_ref ON site (platform_ref) WHERE archived_at IS NULL AND platform_ref IS NOT NULL;
ALTER TABLE site ADD COLUMN device_alerts_enabled boolean NOT NULL DEFAULT false;

-- zone: client data (02-architecture §4). Staff see all rows; a client sees its own rows marked
-- visibility = 'client'; partners see nothing until a policy links rows to their assigned jobs or sites.
CREATE TABLE zone (
  id           uuid PRIMARY KEY,
  client_id    uuid NOT NULL,
  site_id      uuid NOT NULL,
  kind         text NOT NULL CHECK (kind IN ('area', 'gate')),
  -- The platform's unid (areaUnid / gateUnid); the sync matches on it.
  platform_ref text NOT NULL CHECK (platform_ref <> ''),
  name         text NOT NULL CHECK (btrim(name) <> ''),
  -- A gate on the mall's outer boundary (platform isMallGate); areas never are.
  entrance     boolean NOT NULL DEFAULT false CHECK (kind = 'gate' OR NOT entrance),
  visibility   text NOT NULL DEFAULT 'internal' CHECK (visibility IN ('internal', 'client')),
  created_at   timestamptz NOT NULL DEFAULT now(),
  archived_at  timestamptz,
  FOREIGN KEY (site_id, client_id) REFERENCES site (id, client_id),
  UNIQUE (id, site_id)
);
CREATE INDEX zone_client ON zone (client_id);
CREATE UNIQUE INDEX zone_active_ref ON zone (site_id, platform_ref) WHERE archived_at IS NULL;

ALTER TABLE zone ENABLE ROW LEVEL SECURITY;
CREATE POLICY zone_internal ON zone FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
CREATE POLICY zone_client_read ON zone FOR SELECT TO ocs_app
  USING (app.actor_kind() = 'client' AND visibility = 'client' AND client_id = ANY (app.client_ids()));
-- No DELETE: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON zone TO ocs_app;

-- device: what the platform last said. platform_status is separate from the delivery life cycle (status):
-- an installed device can be offline. The platform has no last-seen field, so offline_since is when OCS
-- first saw it offline (R15 measures from it); it is set only while offline.
ALTER TABLE device ADD COLUMN platform_status text CHECK (platform_status IN ('online', 'offline', 'disabled'));
ALTER TABLE device ADD COLUMN offline_since timestamptz;
ALTER TABLE device ADD COLUMN synced_at timestamptz;
ALTER TABLE device ADD CONSTRAINT device_offline_since
  CHECK ((offline_since IS NOT NULL) = (platform_status IS NOT DISTINCT FROM 'offline'));
ALTER TABLE device ADD CONSTRAINT device_id_site UNIQUE (id, site_id);

-- device_channel: which gate each channel of a device counts. Internal only (no client policy). A channel
-- re-bound on the platform is updated in place, never deleted; zone_id is null while unbound.
CREATE TABLE device_channel (
  device_id  uuid NOT NULL,
  channel_no integer NOT NULL CHECK (channel_no >= 1),
  client_id  uuid NOT NULL,
  site_id    uuid NOT NULL,
  zone_id    uuid,
  PRIMARY KEY (device_id, channel_no),
  FOREIGN KEY (device_id, site_id) REFERENCES device (id, site_id),
  FOREIGN KEY (zone_id, site_id) REFERENCES zone (id, site_id),
  FOREIGN KEY (site_id, client_id) REFERENCES site (id, client_id)
);
CREATE INDEX device_channel_zone ON device_channel (zone_id) WHERE zone_id IS NOT NULL;

ALTER TABLE device_channel ENABLE ROW LEVEL SECURITY;
CREATE POLICY device_channel_internal ON device_channel FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
GRANT SELECT, INSERT, UPDATE ON device_channel TO ocs_app;
